using System.IO;
using System.Windows;
using System.Windows.Controls;
using Orbit.Core;
namespace OrbitLauncher;
public partial class MainWindow {
 readonly CancellationTokenSource catalogCts=new();CancellationTokenSource? installCts;bool installing,updatingChoices,catalogLoading;string pickerMode="All",pickerQuery="";VersionEntry? selectedChoice;IReadOnlyList<RemoteVersion> remoteVersions=Array.Empty<RemoteVersion>();List<VersionEntry> choices=new();
 VersionEntry? SelectedChoice=>VersionCombo.SelectedItem as VersionEntry??selectedChoice;
 void UpdateChoices(string? prefer=null){var remote=remoteVersions.ToDictionary(v=>v.Id);choices=versions.Select(v=>v with{Remote=remote.GetValueOrDefault(v.Id)}).Concat(remoteVersions.Where(v=>v.Type is "release" or "snapshot"&&!versions.Any(local=>local.Id==v.Id)).Select(v=>new VersionEntry(v.Id,"Vanilla",v.Id,0){Installed=false,Remote=v})).ToList();
  selectedChoice=choices.FirstOrDefault(v=>v.Id==(prefer??selectedChoice?.Id))??choices.FirstOrDefault(v=>v.Installed&&v.Id=="1.21.1")??choices.FirstOrDefault();ApplyPickerFilter();UpdateLaunchButton();
 }
 void ApplyPickerFilter(){if(VersionCombo==null)return;foreach(var button in new[]{PickerAllTab,PickerInstalledTab,PickerRemoteTab})if(button!=null)button.Background=new System.Windows.Media.SolidColorBrush((System.Windows.Media.Color)System.Windows.Media.ColorConverter.ConvertFromString((string)button.Tag==pickerMode?"#3F593B":"#243139"));updatingChoices=true;try{var filtered=choices.Where(v=>(pickerMode!="Installed"||v.Installed)&&(pickerMode!="Remote"||!v.Installed)&&(v.Installed||SnapshotsBox.IsChecked==true||v.Remote?.Type=="release")&&(pickerQuery.Length==0||v.Id.Contains(pickerQuery,StringComparison.OrdinalIgnoreCase)||v.Loader.Contains(pickerQuery,StringComparison.OrdinalIgnoreCase))).ToList();VersionCombo.ItemsSource=filtered;VersionCombo.SelectedItem=filtered.FirstOrDefault(v=>v.Id==selectedChoice?.Id);}finally{updatingChoices=false;}}
 void UpdateLaunchButton(){var v=SelectedChoice;VersionPickerTitle.Text=v?.Id??"Выбрать версию";PlayButton.IsEnabled=v!=null&&!launching&&!installing;if(!launching&&!installing)PlayButton.Content=v is {Installed:false}?"СКАЧАТЬ   ↓":"ИГРАТЬ   ▶";VersionPickerButton.IsEnabled=!installing&&!launching;}
 async Task LoadCatalogAsync(bool force=false){if(catalogLoading||remoteVersions.Count>0&&!force)return;catalogLoading=true;CatalogStatus.Text="Получение каталога Mojang…";try{using var service=new MojangInstaller();remoteVersions=await service.CatalogAsync(catalogCts.Token);UpdateChoices();CatalogStatus.Text=$"Mojang · {remoteVersions.Count(v=>v.Type=="release")} релизов · поиск по номеру версии";}catch(OperationCanceledException){}catch(Exception e){CatalogStatus.Text="Нет связи с Mojang. Установленные версии доступны.";Log("Каталог: "+e.Message);}finally{catalogLoading=false;}}
 async void VersionPickerOpen_Click(object sender,RoutedEventArgs e){if(installing||launching)return;VersionPopup.IsOpen=true;await LoadCatalogAsync();PickerSearch.Focus();}
 async void ReloadCatalog_Click(object sender,RoutedEventArgs e)=>await LoadCatalogAsync(true);
 void PickerSearch_Changed(object sender,TextChangedEventArgs e){pickerQuery=((TextBox)sender).Text.Trim();if(initialized)ApplyPickerFilter();}
 void PickerTab_Click(object sender,RoutedEventArgs e){pickerMode=(string)((Button)sender).Tag;ApplyPickerFilter();}
 void PickerFilter_Changed(object sender,RoutedEventArgs e){if(initialized)ApplyPickerFilter();}
 static string Bytes(long n)=>n>=1024L*1024*1024?$"{n/(1024d*1024*1024):0.00} ГБ":$"{n/(1024d*1024):0.0} МБ";
 void ShowDownloadProgress(InstallProgress p){DownloadTitle.Text=installing&&selectedChoice!=null?selectedChoice.Id+" · "+p.Stage:p.Stage;DownloadBar.Value=p.Total>0?p.Percent:0;DownloadPercent.Text=p.Total>0?$"{p.Percent:0}%":"";if(p.Total<=0){DownloadDetail.Text="Подготовка файлов · серверы Mojang";return;}string eta=p.Remaining is {} t?(t.TotalHours>=1?$"~{(int)t.TotalHours} ч {t.Minutes} мин":t.TotalMinutes>=1?$"~{(int)t.TotalMinutes} мин {t.Seconds} с":$"~{Math.Max(1,t.Seconds)} с"):"расчёт времени…";DownloadDetail.Text=$"{Bytes(p.Done)} / {Bytes(p.Total)} · {Bytes((long)p.BytesPerSecond)}/с · осталось {eta} · файлов {p.Files}/{p.TotalFiles}";}
 async Task InstallChoiceAsync(VersionEntry v){if(installing||v.Remote==null)return;VersionPopup.IsOpen=false;installing=true;installCts=new();DownloadPanel.Visibility=Visibility.Visible;DownloadTitle.Text="Подготовка "+v.Id;DownloadDetail.Text="Получение описания с серверов Mojang…";DownloadBar.Value=0;DownloadPercent.Text="";CancelDownloadButton.Content="Отмена";PlayButton.Content="ЗАГРУЗКА…";PlayButton.IsEnabled=false;VersionPickerButton.IsEnabled=false;VersionCombo.IsEnabled=false;Status("Скачивание "+v.Id);var root=settings.GameRoot;var token=installCts.Token;
  try{using var service=new MojangInstaller();await service.InstallAsync(root,v.Remote,new Progress<InstallProgress>(ShowDownloadProgress),token);settings.Version=v.Id;await RefreshVersions();selectedChoice=choices.FirstOrDefault(c=>c.Id==v.Id);UpdateChoices(v.Id);DownloadTitle.Text="Установлено · Minecraft "+v.Id;DownloadBar.Value=100;DownloadPercent.Text="100%";DownloadDetail.Text="Клиент, библиотеки, ресурсы и Java готовы. Можно играть офлайн.";Status("Minecraft "+v.Id+" установлен. Нажми «Играть».");Log("Установка Mojang завершена: "+v.Id);}
  catch(OperationCanceledException){DownloadTitle.Text="Загрузка отменена";DownloadDetail.Text="Скачанные файлы сохранены. Выбери эту версию, чтобы продолжить.";Status("Загрузка отменена. Повторная загрузка продолжит с сохранённых файлов.");}
  catch(Exception e){DownloadTitle.Text="Не удалось завершить загрузку";DownloadDetail.Text=e.Message;Status("Ошибка загрузки. Подробности в журнале.",true);Log("Загрузка: "+e.Message);}
  finally{installCts.Dispose();installCts=null;installing=false;VersionCombo.IsEnabled=true;CancelDownloadButton.Content="Скрыть";UpdateLaunchButton();}
 }
 void CancelDownload_Click(object sender,RoutedEventArgs e){if(modInstallCts!=null){modInstallCts.Cancel();CancelDownloadButton.Content="Остановка…";}else if(installCts!=null){installCts.Cancel();CancelDownloadButton.Content="Остановка…";}else DownloadPanel.Visibility=Visibility.Collapsed;}
}
